draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // draw palm tree
  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  ctx.lineTo(W/2, H/2 - 100);
  ctx.stroke();

  // draw leaves
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 100);
  ctx.lineTo(W/2 - 50 + 20 * Math.sin(t), H/2 - 150);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 100);
  ctx.lineTo(W/2 + 50 + 20 * Math.sin(t + Math.PI), H/2 - 150);
  ctx.stroke();

  // draw dates
  ctx.fillStyle = 'brown';
  ctx.beginPath();
  ctx.arc(W/2 - 30 + 10 * Math.sin(t), H/2 - 120, 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2 + 30 + 10 * Math.sin(t + Math.PI), H/2 - 120, 10, 0, 2 * Math.PI);
  ctx.fill();

  // draw stick figure
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H - 50, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H - 30);
  ctx.lineTo(W/2, H - 80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H - 60);
  ctx.lineTo(W/2 - 20, H - 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H - 60);
  ctx.lineTo(W/2 + 20, H - 40);
  ctx.stroke();

  ctx.restore();
}
